INSERT INTO `contact_messages` (`id`, `first_name`, `last_name`, `email`, `phone`, `company`, `service`, `message`, `status`, `created_at`, `updated_at`) VALUES
(16, 'Nicholas', '', 'dobyfinancial@usako.net', '+17087264786', 'Doby', 'Tenue comptable', 'Hello,\r\n\r\nI am an financing representative working with a well-established investment company based in the United States.\r\n\r\nWe offer HARD LOAN FUNDING for commercially viable projects seeking funding for development or expansion.\r\n\r\nThe available financing terms are:\r\n- Annual Interest Rate: 2.5%\r\n- Grace Period: One (1) year / 12 months\r\n- Maximum Funding Term: Ten (10) years\r\n\r\nIf you have a viable startup or an established project that requires funding for expansion, please let us know.\r\n\r\nKindly forward your business plan to info@dobyfinancial.com for initial evaluation by management.\r\n\r\nThank you, and we look forward to hearing from you.\r\n\r\nKind regards,\r\nNicholas Doby\r\nKindly forward your response via this Email: info@dobyfinancial.com\r\nwww.dobyfinancial.com\r\n\r\n\r\n\r\nIf you don\'t want to hear from me on this subject anymore, let me know through the email please.', 'new', '2026-08-06 09:27:08', '2026-08-06 09:27:08'),
(24, 'Missi', 'Naima', 'naimamissi65@gmail.com', '00212661440556', NULL, 'Accompagnement des entreprises', 'Bonjour je suis à la recherche d’une étude pour ouvrir un bureau de change à Marrakech merci', 'new', '2026-08-20 16:33:52', '2026-08-20 16:33:52'),
(25, 'ASSIH', 'Kéméalo', 'dreassih@gmail.com', '+22890979394', 'Mon Guichet Services', 'Accompagnement des entreprises', 'Bonjour MCCG\r\nKéméalo ASSIH, docteure en finance et contrôle de gestion et titulaire d\'un master en comptabilité et contrôle audit; je viens solliciter un partenariat pour la création d\'une filiale de MCCG au Togo.\r\nJe maîtrise la règlementation fiscale et sociale en vigueur au Togo et je suis dans l\'accompagnement et le conseil comptable, fiscal et social depuis quelques années. \r\nComptant sur l\'attention que vous voudriez bien accorder à ma demande, je reste disponible pour toute information complémentaire ou un rendez-vous en vue de mieux échanger des tenants et aboutissants', 'contacted', '2026-09-01 12:38:03', '2026-09-02 17:24:45');

