(2, 'À propos', 'a-propos', 'À propos de MCCG — Votre partenaire de confiance', 'Découvrez MCCG, cabinet de conseil marocain engagé aux côtés des dirigeants et entreprises.', NULL, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(3, 'Services', 'services', 'Services comptables, fiscaux et sociaux | MCCG', 'Découvrez les services MCCG : tenue comptable, conseil fiscal, gestion sociale, paie, accompagnement administratif et conseil aux entreprises.', NULL, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
