INSERT INTO `services` (`id`, `title`, `slug`, `short_description`, `content`, `icon`, `meta_title`, `meta_description`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Tenue comptable', 'tenue-comptable', 'Une information comptable fiable pour sécuriser vos obligations et piloter votre activité.', 'De la tenue des comptes au suivi des états de synthèse, MCCG organise votre information financière et vous apporte une lecture claire de vos chiffres.', 'calculator', 'Tenue comptable — MCCG', 'Une information comptable fiable pour sécuriser vos obligations et piloter votre activité.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(2, 'Conseil fiscal', 'conseil-fiscal', 'Anticipez vos obligations et maîtrisez durablement vos risques fiscaux.', 'Nous vous accompagnons dans vos déclarations, vos choix structurants, vos opérations exceptionnelles et vos relations avec l’administration fiscale marocaine.', 'scale', 'Conseil fiscal — MCCG', 'Anticipez vos obligations et maîtrisez durablement vos risques fiscaux.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(3, 'Audit interne & revue comptable', 'audit-controle', 'Renforcez la fiabilité de vos processus, de vos comptes et de votre gouvernance.', 'Nos missions d’audit interne et de revue comptable identifient les risques, améliorent vos processus et éclairent le pilotage de votre entreprise.', 'check', 'Audit interne & revue comptable — MCCG', 'Renforcez la fiabilité de vos processus, de vos comptes et de votre gouvernance.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(4, 'Gestion sociale & RH', 'paie-social', 'Une gestion sociale précise, confidentielle et conforme à vos obligations.', 'Bulletins de paie, déclarations sociales, contrats et conseil RH : nous simplifions votre quotidien tout en sécurisant vos obligations.', 'users', 'Gestion sociale & RH — MCCG', 'Une gestion sociale précise, confidentielle et conforme à vos obligations.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(5, 'Conseil juridique et administratif', 'creation-entreprise', 'Sécurisez vos décisions et donnez à vos projets le cadre juridique et administratif adapté.', 'Création d’entreprise, formalités et accompagnement administratif : nous vous conseillons dans la limite des prestations autorisées et mobilisons, lorsque nécessaire, des professionnels habilités.', 'building', 'Conseil juridique et administratif — MCCG', 'Sécurisez vos décisions et donnez à vos projets le cadre juridique et administratif adapté.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31'),
(6, 'Accompagnement des entreprises', 'conseil-gestion', 'Des indicateurs clairs et un conseil stratégique pour décider avec confiance.', 'Budgets, tableaux de bord, analyse de rentabilité et optimisation de trésorerie : nos consultants éclairent vos décisions stratégiques.', 'chart', 'Accompagnement des entreprises — MCCG', 'Des indicateurs clairs et un conseil stratégique pour décider avec confiance.', 1, '2026-07-05 20:18:31', '2026-07-05 20:18:31');

